from pjlib import *

C = 'precalculus'

# ---------------------------------------------------------------- Unit 1
project(course=C, unit='equations-inequalities', unit_no=1, unit_name='Equations and Inequalities',
  slug='concert-venue-planner', title='Concert Venue Planner', tagline='Use equations and inequalities to set ticket prices, tolerances, and capacity for a concert.',
  description='Students plan a concert at an outdoor venue. They model revenue with quadratic equations, use absolute value inequalities for sound and temperature tolerances, solve polynomial and rational inequalities for profit and average cost, and solve a radical equation for sound distance.',
  theme='Music & Business', product='Venue Operations Plan', accent='6B3FA0',
  scenario=['Your team is running a summer concert at Riverside Amphitheater. Ticket price affects how many people come, the sound system must stay within safe levels, and the venue has fixed costs no matter how many tickets are sold.',
            'You will solve equations and inequalities to set the price, plan the budget, and keep the crowd safe.'],
  hero=H('RIVERSIDE AMPHITHEATER', '#1E1636', '#3A2E4F', ['🎆', '🌙', '🎶', '⭐'], ['🎸', '🎤', '🥁', '🎟️'],
         [('Demand', '6B3FA0', ['At $40: 3,000 fans', '−50 fans per +$1']), ('Costs', 'C0392B', ['$45,000 fixed', '$6 per fan'])]),
  cards=dict(title='Venue Fact Cards', cols=3, items=[('Capacity', '6B3FA0', ['At most 4,000 fans']), ('Sound Limit', 'C0392B', ['Target 100 dB', 'within ±6 dB']), ('Stage Temp', 'DD7A26', ['Gear safe within', '5°F of 72°F']),
                                                     ('Demand', '2B6CB0', ['n = 3,000 − 50(p − 40)', 'p = ticket price']), ('Costs', '555555', ['C = 45,000 + 6n']), ('Sound Fade', '2E7D4F', ['Level at distance d meters', 'L = 112 − 4√d'])]),
  levels=dict(
    cp2=dict(goals=['I can solve linear and absolute value equations and inequalities.', 'I can solve quadratic equations by factoring or the quadratic formula.', 'I can interpret solutions in context.'],
      parts=[('Tolerances', 'Use the Venue Fact Cards.', [
          Q('Write an absolute value inequality for the safe sound level L.', '|L − 100| ≤ 6', starter='|L − ___| ≤ ___'),
          Q('Solve it. What is the safe range?', '94 ≤ L ≤ 106'),
          Q('Write and solve an inequality for the safe stage temperature T.', '|T − 72| ≤ 5 → 67 ≤ T ≤ 77'),
          Q('The temperature is 79°F. By how much is it outside the safe range?', '2°F above 77°F')]),
        ('Ticket Demand', 'n = 3,000 − 50(p − 40).', [
          Q('Simplify the demand equation.', 'n = 5,000 − 50p'),
          Q('How many fans come if tickets cost $50? $30?', '2,500 and 3,500'),
          Q('Revenue is R = p · n = p(5,000 − 50p). Find R for p = $50.', '50 × 2,500 = $125,000'),
          Q('Solve 5,000 − 50p = 4,000 to find the price that exactly fills the venue.', 'p = $20')]),
        ('Break Even', 'Profit = revenue − cost.', [
          Q('Write the cost when the price is p (use n = 5,000 − 50p).', 'C = 45,000 + 6(5,000 − 50p) = 75,000 − 300p'),
          Q('Profit P = −50p² + 5,300p − 75,000. Use the quadratic formula to find the break-even prices.', 'p = {−5,300 ± √(28,090,000 − 15,000,000)|−100} = {5,300 ∓ 3,618|100} → p ≈ $16.82 or $89.18'),
          Q('Recommend a ticket price and explain using your work.', 'Answers vary; the maximum profit is at p = 53 (vertex), within the break-even range.')])],
      final=['Safe sound and temperature ranges', 'Demand and revenue calculations', 'Break-even prices', 'Recommended ticket price', 'Operations plan'],
      reflect=[('Why is absolute value a good way to describe a tolerance?', 'It measures distance from a target in either direction.'),
               ('What do the two break-even prices mean?', 'Between them the concert makes a profit; outside them it loses money.')]),
    cp1=dict(goals=['I can solve absolute value, quadratic, and polynomial equations and inequalities.', 'I can solve rational inequalities and interpret restrictions.', 'I can use equations to optimize a plan.'],
      parts=[('Revenue & Profit', 'n = 5,000 − 50p and C = 45,000 + 6n.', [
          Q('Write revenue R(p) and profit P(p) as polynomials.', 'R = 5,000p − 50p²; P = −50p² + 5,300p − 75,000'),
          Q('Solve P(p) ≥ 0 to find the prices that make a profit.', '50p² − 5,300p + 75,000 ≤ 0 → 16.82 ≤ p ≤ 89.18'),
          Q('Capacity is at most 4,000 fans. Write and solve the inequality for p.', '5,000 − 50p ≤ 4,000 → p ≥ 20'),
          Q('Combine the conditions. What prices are allowed and profitable? What price maximizes profit?', '20 ≤ p ≤ 89.18; vertex p = 53, profit $65,450')]),
        ('Average Cost', 'The average cost per fan is A(n) = {45,000 + 6n|n}.', [
          Q('Find A(1,000) and A(3,000).', '$51 and $21'),
          Q('Solve A(n) ≤ 20 to find how many fans keep the average cost at most $20.', '{45,000 + 6n|n} ≤ 20 → 45,000 ≤ 14n → n ≥ 3,215 (n > 0)'),
          Q('Why must n > 0 in this inequality? What happens to A(n) as n gets large?', 'n = 0 makes the denominator 0; A(n) approaches $6.'),
          Q('Solve |L − 100| ≤ 6 and |T − 72| < 5. Explain the difference in the endpoints.', '94 ≤ L ≤ 106 (included); 67 < T < 77 (not included)')]),
        ('Sound & Safety', 'The sound level near a speaker: a fan at distance d meters hears L = 112 − 4√d (simplified model).', [
          Q('Solve 112 − 4√d = 100 to find where the level is 100 dB.', '√d = 3 → d = 9 m'),
          Q('Solve 112 − 4√d ≤ 94 to find where it is quiet enough for families.', '√d ≥ 4.5 → d ≥ 20.25 m'),
          Q('Write your venue plan: price, expected fans, profit, and the family seating distance.', 'Answers vary.')])],
      final=['Profit model and profitable price interval', 'Capacity and optimal price', 'Average-cost inequality', 'Sound-distance radical equation', 'Venue operations plan'],
      reflect=[('Why must you check the solutions of a radical equation?', 'Squaring can introduce extraneous solutions.'),
               ('How do rational inequalities differ from polynomial inequalities?', 'You must also consider where the denominator is 0, which can never be part of the solution.')]),
    honors=dict(goals=['I can model a situation with polynomial and rational functions and solve related inequalities.', 'I can solve radical and absolute value equations and check for extraneous roots.', 'I can justify an optimal plan with algebra.'],
      parts=[('Optimal Pricing', 'n = 5,000 − 50p, cost 45,000 + 6n, capacity 4,000.', [
          Q('Find the profit function and the price that maximizes profit by completing the square.', 'P = −50(p − 53)² + 65,450 → p = $53'),
          Q('A sponsor adds $2 per fan. Find the new profit function and optimal price.', 'P = (p − 4)(5,000 − 50p) − 45,000 = −50p² + 5,200p − 65,000; vertex at p = {5,200|100} = $52'),
          Q('Solve P(p) > 50,000 for the original model.', '−50(p − 53)² + 65,450 > 50,000 → (p − 53)² < 309 → 35.42 < p < 70.58'),
          Q('Explain why the capacity constraint (p ≥ 20) does not change the optimal price.', 'p = 53 already gives 2,350 fans ≤ 4,000.')]),
        ('Average Cost & Rational Inequalities', 'Average cost per fan A(n) = {45,000 + 6n|n}.', [
          Q('Solve A(n) < p for the optimal price p = 53 and interpret.', '45,000 + 6n < 53n → n > 957.4 → at least 958 fans'),
          Q('Solve {n − 2,000|n − 4,000} ≤ 0 and give a venue meaning (e.g., comparing attendance to thresholds).', '2,000 ≤ n < 4,000'),
          Q('For which n is A(n) within $1 of its long-run value $6? Solve |A(n) − 6| ≤ 1.', '{45,000|n} ≤ 1 → n ≥ 45,000 (beyond capacity)'),
          Q('Sketch A(n) and describe its asymptotes.', 'Vertical n = 0; horizontal A = 6')]),
        ('Sound Engineering', 'Model: L = 112 − 4√d.', [
          Q('Solve 112 − 4√(d + 5) = 96 and check for extraneous solutions.', '√(d + 5) = 4 → d = 11 ✓'),
          Q('Solve √(d + 7) = d − 5 and check. Interpret one solution.', 'd + 7 = d² − 10d + 25 → d² − 11d + 18 = 0 → d = 9 or 2; d = 2 gives √9 = −3 ✗; d = 9 ✓'),
          Q('Design a seating chart: VIP (≥ 100 dB), general (94–100 dB), family (≤ 94 dB). Give each zone’s distance range.', 'VIP d ≤ 9 m; general 9 ≤ d ≤ 20.25 m; family d ≥ 20.25 m')])],
      final=['Profit function in vertex form and sponsor analysis', 'Profit threshold interval', 'Rational inequalities with asymptotes', 'Radical equations with checks', 'Seating zones and the operations plan'],
      reflect=[('How does vertex form reveal the optimal price immediately?', 'P = a(p − h)² + k with a < 0 has its maximum k at p = h.'),
               ('Why can squaring both sides create an extraneous solution?', 'Squaring makes a negative and its opposite equal, so a solution of the squared equation may not satisfy the original.')])),
  overview=['Students run an outdoor concert. Ticket demand creates quadratic revenue and profit functions, safety tolerances become absolute value inequalities, average cost becomes a rational inequality, and a sound model creates radical equations.',
            'Each solution set is interpreted as a pricing or seating decision.'],
  standards=['A-REI.B.4 Solve quadratic equations', 'A-CED.A.1–3 Create equations and inequalities; constraints', 'A-REI.A.2 Rational and radical equations; extraneous solutions', 'Absolute value and polynomial/rational inequalities'],
  pacing=[['Day 1', 'Launch with a concert poster: how should tickets be priced? Part 1.'], ['Day 2', 'Part 2 rational and polynomial inequalities.'], ['Day 3', 'Part 3 radical equations and the plan.']],
  materials=['Student handout and Venue Fact Cards', 'Graphing calculators', 'Optional: real venue data'],
  differ=dict(cp2='Absolute value tolerances, linear demand, revenue values, and quadratic formula break-even.', cp1='Profit and capacity inequalities, vertex optimization, average-cost rational inequality, and radical equations.',
              honors='Vertex form, sponsor changes, profit thresholds, rational inequality sign analysis, and extraneous roots.'),
  watch=['Writing |L − 100| ≥ 6 for a safe range.', 'Including values that make a denominator 0.', 'Not checking radical solutions.'],
  extensions=['Graph profit with technology and verify the vertex.', 'Add a second ticket tier (VIP).', 'Research decibel safety guidelines.'],
  rubric_app='Equations and inequalities model price, cost, safety, and sound correctly and support the plan.', rubric_comm='Plan includes models, solution sets, a recommended price, and seating zones.')

# ---------------------------------------------------------------- Unit 2
project(course=C, unit='functions', unit_no=2, unit_name='Functions',
  slug='streaming-service-analyst', title='Streaming Service Analyst', tagline='Use function families, transformations, compositions, and inverses to analyze a streaming business.',
  description='Students analyze a music streaming company. They describe domain and range, transform subscriber graphs, model plans with piecewise functions, compose conversion functions, find inverses, and use exponential and logarithmic models for subscriber growth.',
  theme='Technology & Business', product='Analyst Briefing', accent='C0392B',
  scenario=['You are a data analyst at Wavelength, a new music streaming service. Leadership wants to know how pricing plans work, how fast subscribers are growing, and when the company will reach its goals.',
            'You will use functions to model the business and present your findings.'],
  hero=H('WAVELENGTH STREAMING', '#FCEDEC', '#E3E3E3', ['📈', '☁️', '🎧', '💡'], ['📱', '💻', '🎵', '📊'],
         [('Subscribers', 'C0392B', ['S(t) = 20,000(1.08)ᵗ', 't in months']), ('Plans', '2B6CB0', ['Basic $5 · Premium $11', 'Family $17'])]),
  cards=dict(title='Business Data Cards', cols=3, items=[('Data Overage', 'DD7A26', ['$2 per GB over 10 GB', 'on the Basic plan']), ('Exchange', '2E7D4F', ['E(d) = 0.92d', 'dollars → euros']), ('Tax', '555555', ['T(x) = 1.0625x']),
                                                        ('Growth', 'C0392B', ['8% per month', 'from 20,000']), ('Churn', '6B3FA0', ['Old app users fall', '5% per month from 50,000']), ('Goal', '2B6CB0', ['100,000 subscribers'])]),
  levels=dict(
    cp2=dict(goals=['I can identify domain and range and evaluate functions.', 'I can describe transformations of a graph.', 'I can use exponential models to make predictions.'],
      parts=[('Plans as Functions', 'Basic costs $5 per month plus $2 for each GB over 10 GB.', [
          Q('Write the cost C(g) for g GB if g ≤ 10 and if g > 10.', 'C(g) = 5 for 0 ≤ g ≤ 10; C(g) = 5 + 2(g − 10) for g > 10'),
          Q('Find C(6), C(10), and C(14).', '$5, $5, $13'),
          Q('What is a sensible domain and range for C?', 'Domain g ≥ 0; range C ≥ 5'),
          Q('Is C a function? Explain.', 'Yes; each amount of data has exactly one cost.')]),
        ('Transformations', 'The parent graph is y = x².', [
          Q('Describe how y = (x − 3)² + 2 is related to y = x².', 'Shift right 3 and up 2'),
          Q('Describe y = −2x².', 'Reflect over the x-axis and stretch vertically by 2'),
          Q('Write the equation of y = |x| shifted left 4 and down 1.', 'y = |x + 4| − 1'),
          Q('Basic’s price rises $1 per month. How does the graph of C change?', 'It shifts up 1.')]),
        ('Growth', 'S(t) = 20,000(1.08)ᵗ.', [
          Q('Find S(6) and S(12). Round to the nearest subscriber.', '≈ 31,737 and ≈ 50,363'),
          Q('Use a table to find the first month the subscribers reach 100,000.', 't = 21 (≈ 100,677)'),
          Q('Is this growth linear or exponential? How do you know?', 'Exponential; it grows by the same percent (8%) each month.')])],
      final=['Piecewise plan cost with a graph', 'Transformation descriptions', 'Subscriber predictions', 'Month the goal is reached', 'One-page briefing'],
      reflect=[('How does a piecewise function model a real price plan?', 'Different rules apply on different intervals of data use.'),
               ('Why does exponential growth start slow and then speed up?', 'It adds a percent of a growing amount.')]),
    cp1=dict(goals=['I can model with piecewise functions and transformations.', 'I can compose functions and find inverses.', 'I can use exponential and logarithmic functions to solve for time.'],
      parts=[('Pricing Functions', 'Use the Business Data Cards.', [
          Q('Write the Basic plan cost as a piecewise function and graph it.', 'C(g) = 5 (0 ≤ g ≤ 10); 5 + 2(g − 10) (g > 10)'),
          Q('Write the cost with tax, T(C(g)), for g = 14.', 'T(13) = 1.0625 × 13 ≈ $13.81'),
          Q('Write E(T(x)) as a single function and find the euro price of the $11 Premium plan.', 'E(T(x)) = 0.92(1.0625x) = 0.9775x; ≈ €10.75'),
          Q('Find the inverse of E(T(x)). What does it convert?', 'x = {y|0.9775}; it converts euros (with tax) back to dollars before tax.')]),
        ('Transform the Data', 'S(t) = 20,000(1.08)ᵗ.', [
          Q('A marketing campaign adds 5,000 subscribers at launch. Write the new function and describe the transformation.', 'S(t) + 5,000 (shift up) — or 20,000(1.08)ᵗ + 5,000'),
          Q('The campaign starts 3 months late. Write S(t − 3) and describe the shift.', '20,000(1.08)ᵗ⁻³; right 3'),
          Q('Is S(t) even, odd, or neither? Is it one-to-one?', 'Neither; yes, it is one-to-one (increasing).'),
          Q('Find the domain and range of S(t) for t ≥ 0.', 'Domain t ≥ 0; range S ≥ 20,000')]),
        ('Logs & Goals', 'Use logarithms to solve for time.', [
          Q('Solve 20,000(1.08)ᵗ = 100,000 using logarithms.', 't = {ln 5|ln 1.08} ≈ 20.9 months'),
          Q('Old app users: U(t) = 50,000(0.95)ᵗ. When do they fall below 25,000?', 't > {ln 0.5|ln 0.95} ≈ 13.5 → month 14'),
          Q('When will new subscribers be twice the old app users?', '20,000(1.08)ᵗ = 2 × 50,000(0.95)ᵗ → ({1.08|0.95})ᵗ = 5 → t ≈ 12.5 months')])],
      final=['Piecewise pricing and graph', 'Compositions and inverse with meanings', 'Transformed subscriber models', 'Logarithmic time calculations', 'Analyst briefing'],
      reflect=[('What does the composition E(T(x)) mean in words?', 'Add tax first, then convert the taxed price to euros.'),
               ('Why do we use logarithms to solve for time in an exponential model?', 'The variable is in the exponent; logarithms bring it down.')]),
    honors=dict(goals=['I can build, transform, and compose functions to model a business.', 'I can find and interpret inverses and their domains.', 'I can compare exponential and logarithmic models and solve for parameters.'],
      parts=[('Model Building', 'Use the Business Data Cards.', [
          Q('A Family plan is $17 for up to 4 users and $3.50 per extra user. Write F(u) as a piecewise function and find the average cost per user for 6 users.', 'F(u) = 17 (1 ≤ u ≤ 4); 17 + 3.5(u − 4) (u > 4). F(6) = 24 → $4 per user'),
          Q('For how many users is the Family plan’s average cost per user less than the $5 Basic price?', 'For u ≤ 4: {17|u} < 5 → u > 3.4, so u = 4 ($4.25). For u > 4 the average is 3.5 + {3|u} < 5. So 4 or more users.'),
          Q('Find the inverse of C(g) = 5 + 2(g − 10) for g > 10 and state its domain.', 'C⁻¹(c) = {c − 5|2} + 10 for c > 5'),
          Q('Explain why the whole Basic-plan function C(g) (including 0 ≤ g ≤ 10) has no inverse.', 'It is constant on [0, 10]; many inputs give $5, so it is not one-to-one.')]),
        ('Growth Models', 'S(t) = 20,000(1.08)ᵗ, U(t) = 50,000(0.95)ᵗ.', [
          Q('Rewrite S(t) as a continuous model 20,000eᵏᵗ. Find k.', 'k = ln 1.08 ≈ 0.0770'),
          Q('Find the doubling time of S and the half-life of U.', '{ln 2|ln 1.08} ≈ 9.0 months; {ln 0.5|ln 0.95} ≈ 13.5 months'),
          Q('Total users are S(t) + U(t). Find the month when total users are lowest (use a table).', 't = 0: 70,000; t = 3: ≈ 68,063; t = 4: ≈ 67,935; t = 5: ≈ 68,076. The total is lowest at month 4 (about 67,935 users).'),
          Q('Find the inverse of S(t). What question does S⁻¹(n) answer?', 'S⁻¹(n) = {ln(n ÷ 20,000)|ln 1.08}; the month when there are n subscribers')]),
        ('Strategy', 'Leadership has two strategies.', [
          Q('Strategy A: 10% monthly growth from 20,000. Strategy B: linear growth of 3,000 per month from 30,000. When does A pass B?', '20,000(1.1)ᵗ = 30,000 + 3,000t → t ≈ 13.0 months (solve with a table or graph)'),
          Q('Which strategy reaches 100,000 first, and when?', 'A: {ln 5|ln 1.1} ≈ 16.9 months; B: {70,000|3,000} ≈ 23.3 months. A is first.'),
          Q('Write a briefing recommending a strategy, with graphs and at least two function concepts.', 'Answers vary.')])],
      final=['Piecewise Family plan with average cost', 'Inverses with domains', 'Continuous growth, doubling time, and half-life', 'Strategy comparison', 'Briefing with graphs'],
      reflect=[('Why must a function be one-to-one to have an inverse function?', 'Otherwise one output would come from several inputs, and the inverse would not be a function.'),
               ('How do the doubling time and half-life summarize growth and decay?', 'They give the constant time for the quantity to double or halve, independent of the starting amount.')])),
  overview=['Students analyze a streaming service. Pricing plans become piecewise functions, campaigns become transformations, tax and currency conversions become compositions, and subscriber growth uses exponential and logarithmic functions.',
            'Inverses answer "when?" questions about the business.'],
  standards=['F-IF.B.4–5 Interpret functions; domain and range', 'F-BF.B.3 Transformations', 'F-BF.A.1c, B.4 Composition and inverses', 'F-LE.A.4 Logarithms to solve exponential equations'],
  pacing=[['Day 1', 'Launch with streaming plan prices. Part 1 piecewise and compositions.'], ['Day 2', 'Part 2 transformations and properties.'], ['Day 3', 'Part 3 exponential and log models; briefing.']],
  materials=['Student handout and Business Data Cards', 'Graphing calculators or Desmos', 'Slide or poster template'],
  differ=dict(cp2='Piecewise cost, basic transformations, and exponential predictions with tables.', cp1='Compositions, inverses, transformed models, and logarithms to solve for time.',
              honors='Average cost from a piecewise model, inverse domains, continuous growth, doubling time, half-life, and strategy comparison.'),
  watch=['Shifting the wrong direction for f(x − h).', 'Composing in the wrong order.', 'Treating 8% growth as adding 0.08 instead of multiplying by 1.08.'],
  extensions=['Use real subscriber data from a news article.', 'Graph all models in Desmos.', 'Add a logistic model with a cap.'],
  rubric_app='Functions, transformations, compositions, inverses, and exponential models are built and interpreted correctly.', rubric_comm='Briefing includes models, graphs, calculations, and a recommendation.')

